    earliestStart(id) {
        if (!this.tasks.has(id)) {
            throw new Error(`Unknown task id '${id}'`);
        }

        // If no dependencies, earliest start is 0
        if (!this.dependencies.has(id) || this.dependencies.get(id).size === 0) {
            return 0;
        }

        // Find the latest finish time among dependencies
        let latestFinish = 0;
